<?php if (!defined('ABSPATH')) { exit; } get_header(); ?>
<main id="tresc" tabindex="-1" class="wrap document-main"><p class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">Strona główna</a> / Artykuły</p><div class="document-heading"><p class="eyebrow">Czytaj, odkrywaj, bądź na bieżąco</p><h1><?php if (is_search()) { echo 'Wyniki wyszukiwania: ' . esc_html(get_search_query()); } elseif (is_category()) { single_cat_title(); } elseif (is_archive()) { echo esc_html(wp_strip_all_tags(get_the_archive_title())); } else { echo 'Artykuły i aktualności'; } ?></h1></div>
